Rules.InvariantScript:
If(
    galAvailableVolunteers.Selected.Availability.Value <> "Available",

    Notify(
        "Error: This volunteer is not available. Please choose an available volunteer.",
        NotificationType.Error
    ),

    Set(
        varNewAssignmentID,
        "ASN-" & Text(Now(), "yyyymmddhhmmss")
    );

    Patch(
        Assignments,
        Defaults(Assignments),
        {
            Title: varNewAssignmentID,
            AssignmentID: varNewAssignmentID,
            IncidentID: varSelectedIncident.IncidentID,
            VolunteerID: galAvailableVolunteers.Selected.VolunteerID,
            VolunteerName: galAvailableVolunteers.Selected.FullName,
            VolunteerEmail: galAvailableVolunteers.Selected.Email,
            AssignedBy: User().Email,
            AssignedTime: Now(),
            ResponseStatus: {Value: "Pending"},
            Notes: txtAssignmentNotes.Text
        }
    );

    Patch(
        Volunteers,
        galAvailableVolunteers.Selected,
        {
            Availability: {Value: "Assigned"}
        }
    );

    Patch(
        'List 1: Incidents',
        varSelectedIncident,
        {
            Status: {Value: "Assigned"}
        }
    );

    Refresh(Assignments);
    Refresh(Volunteers);
    Refresh('List 1: Incidents');

    Notify(
        "Volunteer assigned successfully.",
        NotificationType.Success
    );

    Navigate(ManagerDashboardScreen, ScreenTransition.Fade)
)
